// Function to run a DuckDuckGo search and return parsed results
async function ddgSearch(query) {
  const url = `https://duckduckgo.com/?q=${encodeURIComponent(query)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });

  return await browserjs(tabId, () => {
    const articles = Array.from(document.querySelectorAll('article'));
    return articles.map(art => {
      const a = art.querySelector('h2 a, a[data-testid="result-title-a"]');
      const snippet = art.querySelector('[data-result="snippet"], div:nth-child(3)')?.innerText || art.innerText;
      return {
        title: a?.innerText,
        url: a?.href,
        snippet: snippet.replace(/\n+/g, ' ').slice(0, 300)
      };
    }).filter(r => r.title && r.url);
  });
}

