async function ddgSearch(query) {
  const url = `https://duckduckgo.com/?q=${encodeURIComponent(query)}`;
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });

  return await browserjs(tabId, () => {
    const articles = Array.from(document.querySelectorAll('article'));
    return articles.map(art => {
      const a = art.querySelector('h2 a, a[data-testid="result-title-a"]');
      const snippet = art.querySelector('[data-result="snippet"], div:nth-child(3)')?.innerText || art.innerText;
      return {
        title: a?.innerText,
        url: a?.href,
        snippet: snippet.replace(/\n+/g, ' ').slice(0, 300)
      };
    }).filter(r => r.title && r.url);
  });
}

// 1. LAPL search
const laplResults = await ddgSearch("site:lapl.org board games");
console.log("LAPL results:", JSON.stringify(laplResults.slice(0, 4), null, 2));

// 2. Eventbrite search
const eventbriteResults = await ddgSearch("site:eventbrite.com board game night los angeles recurring");
console.log("Eventbrite results:", JSON.stringify(eventbriteResults.slice(0, 4), null, 2));

// 3. Guildhall Burbank
const guildhallResults = await ddgSearch("Guildhall Burbank board games events");
console.log("Guildhall results:", JSON.stringify(guildhallResults.slice(0, 3), null, 2));

// 4. The Game Chest Torrance
const gameChestResults = await ddgSearch("The Game Chest Torrance calendar events");
console.log("Game Chest results:", JSON.stringify(gameChestResults.slice(0, 3), null, 2));

